function sigmoid(z){ return 1/(1+Math.exp(-z)); }
function train(X, y, lr, iters){ var n=X.length, d=X[0].length; var w=new Array(d+1).fill(0);
  for(var it=0; it<iters; it++){ for(var i=0;i<n;i++){ var z=w[0]; for(var j=0;j<d;j++) z+=w[j+1]*X[i][j];
      var p=sigmoid(z); var err=p-y[i]; w[0]-=lr*err; for(var j=0;j<d;j++) w[j+1]-=lr*err*X[i][j]; } }
  return w; }
function predict(w, x){ var z=w[0]; for(var j=0;j<x.length;j++) z+=w[j+1]*x[j]; return sigmoid(z)>=0.5?1:0; }
var EXPORTS={sigmoid:sigmoid, train:train, predict:predict};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LogisticRegForgePure = EXPORTS; }
